sys_ws_operation.operation_script:
(function process( /*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    if (request.method == "GET") {
        response.setStatus(405);
        response.setBody({
            status: "failure",
            error: {
                message: "Method not Supported",
                detail: "GET method not supported for API"
            }
        });
        return;
    }

    try {
        var requestData = request.body.data;
        var u_button_label = requestData.u_button_label; // e.g., markbtn_1, markbtn_2
        var u_read_flag = requestData.u_read_flag; // true or false

        // Define the system property name
        var propertyName = 'Mark as complete button property walk';

        // Get the current value of the system property (stored as a JSON string)
        var currentValue = gs.getProperty(propertyName);

        // Parse the current value into an object, or initialize an empty object if it doesn't exist
        var buttonStates = currentValue ? JSON.parse(currentValue) : {};

        // Update the state for the specific button
        buttonStates[u_button_label] = u_read_flag;

        // Convert the updated object back to a JSON string and save it
        gs.setProperty(propertyName, JSON.stringify(buttonStates));

        // Determine status for response
        var status = u_read_flag ? "Complete" : "Incomplete";

        response.setBody({
            status: 'success',
            message: `Button '${u_button_label}' updated to ${status} in system property '${propertyName}'.`
        });
    } catch (e) {
        response.setStatus(500);
        response.setBody({
            status: 'error',
            message: e.message
        });
    }
})(request, response);
